<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/layout.php';
$admin=require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'create');try{
if($action==='create'){$name=trim((string)($_POST['name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$pass=(string)($_POST['password']??'');$role=(string)($_POST['role']??'comercial');if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<10)throw new RuntimeException('Informe nome, e-mail válido e senha com pelo menos 10 caracteres.');if(!in_array($role,['admin','gestor','comercial','suporte','leitura'],true))throw new RuntimeException('Perfil inválido.');$q=$pdo->prepare('INSERT INTO users(name,email,password_hash,role,active) VALUES(?,?,?,?,1)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);$id=(int)$pdo->lastInsertId();audit($pdo,(int)$admin['id'],'create','user',$id,['role'=>$role]);flash('success','Usuário criado.');
}elseif($action==='toggle'){$id=(int)($_POST['id']??0);if($id===(int)$admin['id'])throw new RuntimeException('Sua própria conta não pode ser desativada nesta tela.');$pdo->prepare('UPDATE users SET active=IF(active=1,0,1) WHERE id=?')->execute([$id]);audit($pdo,(int)$admin['id'],'toggle_active','user',$id);flash('success','Status do usuário atualizado.');
}elseif($action==='password'){$id=(int)($_POST['id']??0);$pass=(string)($_POST['new_password']??'');if(strlen($pass)<10)throw new RuntimeException('A nova senha deve ter pelo menos 10 caracteres.');$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($pass,PASSWORD_DEFAULT),$id]);audit($pdo,(int)$admin['id'],'reset_password','user',$id);flash('success','Senha alterada pelo administrador.');}
}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('usuarios.php');}
$rows=$pdo->query('SELECT id,name,email,role,active,last_login_at FROM users ORDER BY name')->fetchAll();page_header('Usuários','usuarios');
?>
<div class="page-actions"><div><span class="eyebrow">ACESSO</span><h2>Usuários do CRM</h2><p>Somente o administrador inicial existe após a instalação. Nenhum colaborador de exemplo é criado.</p></div></div>
<div class="card"><div class="card-title"><div><span class="tag">NOVO USUÁRIO</span><h3>Cadastrar acesso</h3></div></div><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="create"><label><span>Nome</span><input name="name" required></label><label><span>E-mail</span><input type="email" name="email" required></label><label><span>Perfil</span><select name="role"><option value="comercial">Comercial</option><option value="suporte">Suporte</option><option value="gestor">Gestor</option><option value="leitura">Leitura</option><option value="admin">Administrador</option></select></label><label><span>Senha inicial</span><input type="password" name="password" minlength="10" required></label><div class="span-2 form-actions"><button class="btn btn-primary" type="submit">Criar usuário</button></div></form></div>
<div class="card"><div class="card-title"><div><span class="tag">CONTAS</span><h3>Usuários cadastrados</h3></div></div><div class="table-wrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Status</th><th>Último acesso</th><th>Administração</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['name']) ?></strong></td><td><?= e($row['email']) ?></td><td><?= e(ucfirst($row['role'])) ?></td><td><span class="status <?= (int)$row['active']?'status-ganha':'status-perdida' ?>"><?= (int)$row['active']?'Ativo':'Inativo' ?></span></td><td><?= e($row['last_login_at']?:'—') ?></td><td><div class="user-actions"><form method="post" class="cell-form"><?= csrf_field() ?><input type="hidden" name="action" value="password"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="password" name="new_password" minlength="10" placeholder="Nova senha" required><button class="link-btn" type="submit">Trocar senha</button></form><?php if((int)$row['id']!==(int)$admin['id']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="link-btn <?= (int)$row['active']?'danger':'' ?>" type="submit"><?= (int)$row['active']?'Desativar':'Ativar' ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php page_footer(); ?>